//! HTTP adapter: routing by hand so that every response, including framework-level failures,
//! is a spec-shaped problem+json and the error precedence is ours (ADR-0003).
use crate::domain::{self, FieldError, Precondition};
use crate::store::{self, Note, UpdateOutcome, User};
use axum::body::Body;
use axum::extract::{Request, State};
use axum::http::{header, HeaderMap, HeaderValue, Method, StatusCode};
use axum::response::Response;
use http_body_util::BodyExt;
use rusqlite::Connection;
use serde::Serialize;
use serde_json::{json, Value};
use std::sync::{Arc, Mutex};

pub type Db = Arc<Mutex<Connection>>;

/// Stop buffering at the limit but keep draining (bounded) so the client can read our 413.
const DRAIN_CAP: usize = 64 * 1024 * 1024;

struct RawBody {
    bytes: Vec<u8>,
    overflow: bool,
}

async fn read_body(mut body: Body) -> RawBody {
    let (mut bytes, mut seen, mut overflow) = (Vec::new(), 0usize, false);
    while let Some(Ok(frame)) = body.frame().await {
        if let Ok(data) = frame.into_data() {
            seen += data.len();
            if seen > domain::MAX_REQUEST_BYTES {
                overflow = true;
                bytes.clear();
            } else if !overflow {
                bytes.extend_from_slice(&data);
            }
            if seen > DRAIN_CAP {
                break;
            }
        }
    }
    RawBody { bytes, overflow }
}

// ---- responses ----------------------------------------------------------------------------

fn respond(status: StatusCode, content_type: &str, body: Vec<u8>) -> Response {
    let mut r = Response::new(Body::from(body));
    *r.status_mut() = status;
    r.headers_mut().insert(header::CONTENT_TYPE, HeaderValue::from_str(content_type).unwrap());
    r
}

fn json_response<T: Serialize>(status: StatusCode, v: &T) -> Response {
    respond(status, "application/json", serde_json::to_vec(v).unwrap())
}

fn with_etag(mut r: Response, version: i64) -> Response {
    r.headers_mut().insert(header::ETAG, HeaderValue::from_str(&domain::etag(version)).unwrap());
    r
}

fn problem(status: StatusCode, title: &str, detail: Option<&str>, errors: Option<&[FieldError]>) -> Response {
    let slug = title.to_lowercase().replace(' ', "-");
    let mut v = json!({
        "type": format!("https://teamnotes.example/problems/{slug}"),
        "title": title,
        "status": status.as_u16(),
    });
    if let Some(d) = detail {
        v["detail"] = json!(d);
    }
    if let Some(es) = errors {
        v["errors"] = es.iter().map(|e| json!({"field": e.field, "message": e.message})).collect();
    }
    respond(status, "application/problem+json", serde_json::to_vec(&v).unwrap())
}

/// One body for every kind of "not found / not visible", so they are byte-identical.
fn not_found() -> Response {
    problem(StatusCode::NOT_FOUND, "Not Found", None, None)
}
fn unauthorized() -> Response {
    let mut r = problem(StatusCode::UNAUTHORIZED, "Unauthorized", Some("A valid bearer token is required"), None);
    r.headers_mut().insert(header::WWW_AUTHENTICATE, HeaderValue::from_static("Bearer"));
    r
}
fn internal(e: rusqlite::Error) -> Response {
    eprintln!("db error: {e}");
    problem(StatusCode::INTERNAL_SERVER_ERROR, "Internal Server Error", None, None)
}
fn invalid(errors: &[FieldError]) -> Response {
    problem(StatusCode::UNPROCESSABLE_ENTITY, "Unprocessable Entity", Some("Validation failed"), Some(errors))
}

// ---- request handling ---------------------------------------------------------------------

fn header_str<'a>(h: &'a HeaderMap, name: header::HeaderName) -> Option<&'a str> {
    h.get(name).and_then(|v| v.to_str().ok())
}

/// 415 → 413 → 400, then the parsed JSON value (validation is the caller's 422 step).
fn json_body(headers: &HeaderMap, raw: &RawBody) -> Result<Value, Response> {
    let sent = !raw.bytes.is_empty() || raw.overflow;
    if sent && !domain::is_json_content_type(header_str(headers, header::CONTENT_TYPE)) {
        return Err(problem(StatusCode::UNSUPPORTED_MEDIA_TYPE, "Unsupported Media Type", Some("Content-Type must be application/json"), None));
    }
    if raw.overflow {
        let mut r = problem(StatusCode::PAYLOAD_TOO_LARGE, "Payload Too Large", Some("Request body exceeds 2 MiB"), None);
        r.headers_mut().insert(header::CONNECTION, HeaderValue::from_static("close"));
        return Err(r);
    }
    serde_json::from_slice(&raw.bytes)
        .map_err(|_| problem(StatusCode::BAD_REQUEST, "Bad Request", Some("Request body is not valid JSON"), None))
}

fn note_response(status: StatusCode, n: &Note) -> Response {
    with_etag(json_response(status, n), n.version)
}

pub async fn handle(State(db): State<Db>, req: Request) -> Response {
    let (parts, body) = req.into_parts();
    let raw = read_body(body).await;
    let path = parts.uri.path().to_string();
    let segs: Vec<&str> = path.trim_start_matches('/').split('/').collect();

    if parts.method == Method::GET && segs == ["health"] {
        return json_response(StatusCode::OK, &json!({"status": "ok"}));
    }
    let conn = db.lock().unwrap_or_else(|p| p.into_inner());
    let user = match domain::bearer_token(header_str(&parts.headers, header::AUTHORIZATION)) {
        None => return unauthorized(),
        Some(t) => match store::user_by_token(&conn, t) {
            Ok(Some(u)) => u,
            Ok(None) => return unauthorized(),
            Err(e) => return internal(e),
        },
    };
    let result = route(&conn, &user, &parts.method, &segs, &parts.headers, &raw, parts.uri.query());
    result.unwrap_or_else(internal)
}

/// `archived` accepts exactly `true` or `false`; anything else is a 422 on `archived`.
fn archived_flag(query: Option<&str>) -> Result<bool, Response> {
    let Some(q) = query else { return Ok(false) };
    match q.split('&').find_map(|p| p.strip_prefix("archived=").or((p == "archived").then_some(""))) {
        None | Some("false") => Ok(false),
        Some("true") => Ok(true),
        Some(_) => Err(invalid(&[FieldError { field: "archived".into(), message: "must be true or false".into() }])),
    }
}

/// Non-empty body that is not JSON: 415 (for operations that otherwise ignore the body).
fn ignored_body_check(headers: &HeaderMap, raw: &RawBody) -> Option<Response> {
    let sent = !raw.bytes.is_empty() || raw.overflow;
    (sent && !domain::is_json_content_type(header_str(headers, header::CONTENT_TYPE)))
        .then(|| problem(StatusCode::UNSUPPORTED_MEDIA_TYPE, "Unsupported Media Type", Some("Content-Type must be application/json"), None))
}

fn route(
    c: &Connection,
    user: &User,
    method: &Method,
    segs: &[&str],
    headers: &HeaderMap,
    raw: &RawBody,
    query: Option<&str>,
) -> rusqlite::Result<Response> {
    Ok(match (method, segs) {
        (&Method::GET, ["me"]) => {
            json_response(StatusCode::OK, &json!({"id": user.id, "name": user.name, "teams": store::teams_of(c, &user.id)?}))
        }
        (&Method::GET, ["teams"]) => json_response(StatusCode::OK, &json!({"items": store::teams_of(c, &user.id)?})),
        (&Method::GET, ["teams", team, "notes"]) => {
            if !store::is_member(c, team, &user.id)? {
                return Ok(not_found());
            }
            match archived_flag(query) {
                Ok(a) => json_response(StatusCode::OK, &json!({"items": store::list_notes(c, team, a)?})),
                Err(r) => r,
            }
        }
        (&Method::POST, ["teams", team, "notes"]) => {
            if !store::is_member(c, team, &user.id)? {
                return Ok(not_found());
            }
            let value = match json_body(headers, raw) {
                Ok(v) => v,
                Err(r) => return Ok(r),
            };
            match domain::parse_create(&value) {
                Err(errs) => invalid(&errs),
                Ok(new) => {
                    let n = store::insert_note(c, team, &user.id, &new)?;
                    let mut r = note_response(StatusCode::CREATED, &n);
                    r.headers_mut().insert(header::LOCATION, HeaderValue::from_str(&format!("/notes/{}", n.id)).unwrap());
                    r
                }
            }
        }
        (&Method::GET, ["notes", id]) => match store::note_for_member(c, id, &user.id)? {
            Some(n) if n.deleted_at.is_none() => note_response(StatusCode::OK, &n),
            _ => not_found(),
        },
        (&Method::PATCH, ["notes", id]) => match store::note_for_member(c, id, &user.id)? {
            Some(n) if n.deleted_at.is_none() => patch_note(c, &n, headers, raw)?,
            _ => not_found(),
        },
        (&Method::DELETE, ["notes", id]) => match store::note_for_member(c, id, &user.id)? {
            Some(n) => {
                if let Some(r) = ignored_body_check(headers, raw) {
                    return Ok(r);
                }
                store::soft_delete(c, &n.id)?;
                respond(StatusCode::NO_CONTENT, "application/json", Vec::new())
            }
            None => not_found(),
        },
        (&Method::POST, ["notes", id, "restore"]) => match store::note_for_member(c, id, &user.id)? {
            Some(_) if ignored_body_check(headers, raw).is_some() => ignored_body_check(headers, raw).unwrap(),
            Some(n) => match store::restore(c, &n.id)? {
                Some(n) => note_response(StatusCode::OK, &n),
                None => not_found(),
            },
            None => not_found(),
        },
        _ => not_found(),
    })
}

fn patch_note(c: &Connection, note: &Note, headers: &HeaderMap, raw: &RawBody) -> rusqlite::Result<Response> {
    let value = match json_body(headers, raw) {
        Ok(v) => v,
        Err(r) => return Ok(r),
    };
    let patch = match domain::parse_patch(&value) {
        Ok(p) => p,
        Err(errs) => return Ok(invalid(&errs)),
    };
    let pre = domain::parse_if_match(header_str(headers, header::IF_MATCH));
    if pre == Precondition::Required {
        return Ok(problem(StatusCode::PRECONDITION_REQUIRED, "Precondition Required", Some("A specific If-Match ETag is required"), None));
    }
    // The check and the increment stay one conditional UPDATE; `expected` is the version
    // the list names that equals the current one (or -1, which matches nothing).
    let expected = if pre.matches(note.version) { note.version } else { -1 };
    Ok(match store::update_note(c, &note.id, expected, &patch)? {
        UpdateOutcome::Updated(n) => note_response(StatusCode::OK, &n),
        UpdateOutcome::Stale(n) => with_etag(
            problem(StatusCode::PRECONDITION_FAILED, "Precondition Failed", Some("If-Match does not match the current version"), None),
            n.version,
        ),
        UpdateOutcome::Gone => not_found(),
    })
}
//! SQLite store. All SQL lives here.
use crate::domain::{NewNote, NotePatch};
use rusqlite::{params, Connection, OptionalExtension, Row};
use serde::Serialize;
use sha2::{Digest, Sha256};

const SCHEMA: &str = include_str!("../../../spec/schema.sql");

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Note {
    pub id: String,
    pub team_id: String,
    pub author_id: String,
    pub title: String,
    pub body: String,
    pub version: i64,
    pub created_at: String,
    pub updated_at: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub deleted_at: Option<String>,
}

#[derive(Debug, Clone, Serialize)]
pub struct Team {
    pub id: String,
    pub name: String,
    pub role: String,
}

#[derive(Debug, Clone)]
pub struct User {
    pub id: String,
    pub name: String,
}

pub enum UpdateOutcome {
    Updated(Note),
    /// Current note differs from the expected version (carries the current note).
    Stale(Note),
    Gone,
}

pub fn open(path: &str) -> rusqlite::Result<Connection> {
    let conn = Connection::open(path)?;
    conn.execute_batch(SCHEMA)?;
    Ok(conn)
}

pub fn now() -> String {
    chrono::Utc::now().format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string()
}

const NOTE_COLS: &str = "n.id, n.team_id, n.author_id, n.title, n.body, n.version, n.created_at, n.updated_at, n.deleted_at";

fn note_from(r: &Row) -> rusqlite::Result<Note> {
    Ok(Note {
        id: r.get(0)?,
        team_id: r.get(1)?,
        author_id: r.get(2)?,
        title: r.get(3)?,
        body: r.get(4)?,
        version: r.get(5)?,
        created_at: r.get(6)?,
        updated_at: r.get(7)?,
        deleted_at: r.get(8)?,
    })
}

pub fn user_by_token(c: &Connection, token: &str) -> rusqlite::Result<Option<User>> {
    let hash: String = Sha256::digest(token.as_bytes()).iter().map(|b| format!("{b:02x}")).collect();
    c.query_row("SELECT id, name FROM users WHERE token_hash = ?", [hash], |r| {
        Ok(User { id: r.get(0)?, name: r.get(1)? })
    })
    .optional()
}

pub fn teams_of(c: &Connection, user_id: &str) -> rusqlite::Result<Vec<Team>> {
    let mut st = c.prepare(
        "SELECT t.id, t.name, m.role FROM memberships m JOIN teams t ON t.id = m.team_id \
         WHERE m.user_id = ? ORDER BY t.id",
    )?;
    let rows = st.query_map([user_id], |r| Ok(Team { id: r.get(0)?, name: r.get(1)?, role: r.get(2)? }))?;
    rows.collect()
}

pub fn is_member(c: &Connection, team_id: &str, user_id: &str) -> rusqlite::Result<bool> {
    c.query_row("SELECT 1 FROM memberships WHERE team_id = ? AND user_id = ?", [team_id, user_id], |_| Ok(()))
        .optional()
        .map(|o| o.is_some())
}

/// The note, only if the user belongs to its team. Includes soft-deleted notes.
pub fn note_for_member(c: &Connection, note_id: &str, user_id: &str) -> rusqlite::Result<Option<Note>> {
    c.query_row(
        &format!(
            "SELECT {NOTE_COLS} FROM notes n JOIN memberships m ON m.team_id = n.team_id AND m.user_id = ? WHERE n.id = ?"
        ),
        [user_id, note_id],
        note_from,
    )
    .optional()
}

pub fn list_notes(c: &Connection, team_id: &str, archived: bool) -> rusqlite::Result<Vec<Note>> {
    let cond = if archived { "IS NOT NULL" } else { "IS NULL" };
    let mut st = c.prepare(&format!(
        "SELECT {NOTE_COLS} FROM notes n WHERE n.team_id = ? AND n.deleted_at {cond} ORDER BY n.seq DESC"
    ))?;
    let rows = st.query_map([team_id], note_from)?;
    rows.collect()
}

pub fn insert_note(c: &Connection, team_id: &str, author_id: &str, new: &NewNote) -> rusqlite::Result<Note> {
    let id = uuid::Uuid::new_v4().to_string();
    let ts = now();
    c.execute(
        "INSERT INTO notes (id, team_id, author_id, title, body, version, created_at, updated_at) \
         VALUES (?, ?, ?, ?, ?, 1, ?, ?)",
        params![id, team_id, author_id, new.title.as_str(), new.body.as_str(), ts, ts],
    )?;
    Ok(Note {
        id,
        team_id: team_id.into(),
        author_id: author_id.into(),
        title: new.title.as_str().into(),
        body: new.body.as_str().into(),
        version: 1,
        created_at: ts.clone(),
        updated_at: ts,
        deleted_at: None,
    })
}

fn reload(c: &Connection, note_id: &str) -> rusqlite::Result<Option<Note>> {
    c.query_row(&format!("SELECT {NOTE_COLS} FROM notes n WHERE n.id = ?"), [note_id], note_from).optional()
}

/// Compare-and-set update inside a single statement (ADR-0001).
pub fn update_note(c: &Connection, note_id: &str, expected: i64, patch: &NotePatch) -> rusqlite::Result<UpdateOutcome> {
    let changed = c.execute(
        "UPDATE notes SET title = COALESCE(?, title), body = COALESCE(?, body), \
         version = version + 1, updated_at = ? \
         WHERE id = ? AND version = ? AND deleted_at IS NULL",
        params![patch.title.as_ref().map(|t| t.as_str()), patch.body.as_ref().map(|b| b.as_str()), now(), note_id, expected],
    )?;
    let cur = reload(c, note_id)?;
    Ok(match (changed, cur) {
        (1, Some(n)) => UpdateOutcome::Updated(n),
        (_, Some(n)) if n.deleted_at.is_none() => UpdateOutcome::Stale(n),
        _ => UpdateOutcome::Gone,
    })
}

pub fn soft_delete(c: &Connection, note_id: &str) -> rusqlite::Result<()> {
    c.execute("UPDATE notes SET deleted_at = ? WHERE id = ? AND deleted_at IS NULL", params![now(), note_id])?;
    Ok(())
}

/// Restores a deleted note (version + 1). A live note is returned unchanged.
pub fn restore(c: &Connection, note_id: &str) -> rusqlite::Result<Option<Note>> {
    c.execute(
        "UPDATE notes SET deleted_at = NULL, version = version + 1, updated_at = ? WHERE id = ? AND deleted_at IS NOT NULL",
        params![now(), note_id],
    )?;
    reload(c, note_id)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::domain::{parse_create, parse_patch};
    use serde_json::json;

    fn db() -> Connection {
        open(":memory:").unwrap()
    }

    #[test]
    fn seed_tokens_resolve() {
        let c = db();
        assert_eq!(user_by_token(&c, "tok_alice").unwrap().unwrap().id, "alice");
        assert!(user_by_token(&c, "nope").unwrap().is_none());
    }

    #[test]
    fn cas_update_soft_delete_restore() {
        let c = db();
        let n = insert_note(&c, "team-red", "alice", &parse_create(&json!({"title": "a"})).unwrap()).unwrap();
        let p = parse_patch(&json!({"title": "b"})).unwrap();
        assert!(matches!(update_note(&c, &n.id, 1, &p).unwrap(), UpdateOutcome::Updated(x) if x.version == 2));
        assert!(matches!(update_note(&c, &n.id, 1, &p).unwrap(), UpdateOutcome::Stale(x) if x.version == 2));
        soft_delete(&c, &n.id).unwrap();
        assert!(matches!(update_note(&c, &n.id, 2, &p).unwrap(), UpdateOutcome::Gone));
        assert_eq!(list_notes(&c, "team-red", true).unwrap().len(), 1);
        let r = restore(&c, &n.id).unwrap().unwrap();
        assert_eq!((r.version, r.deleted_at), (3, None));
        assert_eq!(restore(&c, &n.id).unwrap().unwrap().version, 3);
    }

    #[test]
    fn membership_scopes_visibility() {
        let c = db();
        let n = insert_note(&c, "team-red", "alice", &parse_create(&json!({"title": "a"})).unwrap()).unwrap();
        assert!(note_for_member(&c, &n.id, "bob").unwrap().is_some());
        assert!(note_for_member(&c, &n.id, "carol").unwrap().is_none());
    }
}
mod domain;
mod http;
mod store;

use std::sync::{Arc, Mutex};

#[tokio::main]
async fn main() {
    let db_path = std::env::var("DB_PATH").unwrap_or_else(|_| ":memory:".into());
    let port = std::env::var("PORT").unwrap_or_else(|_| "3006".into());
    let conn = store::open(&db_path).expect("open database");
    let db: http::Db = Arc::new(Mutex::new(conn));
    let app = axum::Router::new().fallback(http::handle).with_state(db);
    let listener = tokio::net::TcpListener::bind(format!("0.0.0.0:{port}")).await.expect("bind");
    println!("team-notes (rust) listening on :{port}");
    axum::serve(listener, app).await.expect("serve");
}
#!/usr/bin/env bash
cd "$(dirname "$0")" && exec cargo run --release
//! Pure domain: parse untrusted JSON once into typed values, so invalid notes cannot be represented.
use serde_json::Value;

pub const MAX_TITLE: usize = 200;
pub const MAX_BODY: usize = 100_000;
pub const MAX_REQUEST_BYTES: usize = 2 * 1024 * 1024;

const READ_ONLY: [&str; 7] = ["id", "teamId", "authorId", "version", "createdAt", "updatedAt", "deletedAt"];

#[derive(Debug, Clone, PartialEq)]
pub struct FieldError {
    pub field: String,
    pub message: String,
}

fn err(field: &str, message: &str) -> FieldError {
    FieldError { field: field.to_string(), message: message.to_string() }
}

/// A trimmed title of 1..=200 code points.
#[derive(Debug, Clone, PartialEq)]
pub struct Title(String);

impl Title {
    pub fn parse(v: &Value) -> Result<Title, FieldError> {
        let s = v.as_str().ok_or_else(|| err("title", "must be a string"))?;
        let t = s.trim();
        let n = t.chars().count();
        if n == 0 || n > MAX_TITLE {
            return Err(err("title", "must be 1-200 characters after trimming"));
        }
        Ok(Title(t.to_string()))
    }
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

/// A body of at most 100,000 code points.
#[derive(Debug, Clone, PartialEq)]
pub struct Body(String);

impl Body {
    pub fn parse(v: &Value) -> Result<Body, FieldError> {
        let s = v.as_str().ok_or_else(|| err("body", "must be a string"))?;
        if s.chars().count() > MAX_BODY {
            return Err(err("body", "must be at most 100000 characters"));
        }
        Ok(Body(s.to_string()))
    }
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

#[derive(Debug)]
pub struct NewNote {
    pub title: Title,
    pub body: Body,
}

#[derive(Debug)]
pub struct NotePatch {
    pub title: Option<Title>,
    pub body: Option<Body>,
}

struct Fields {
    title: Option<Title>,
    body: Option<Body>,
    count: usize,
    has_title_key: bool,
}

/// Validate the shared fields, collecting every problem.
fn parse_fields(v: &Value, errors: &mut Vec<FieldError>) -> Option<Fields> {
    let Some(obj) = v.as_object() else {
        errors.push(err("$", "request body must be a JSON object"));
        return None;
    };
    let mut f = Fields { title: None, body: None, count: obj.len(), has_title_key: obj.contains_key("title") };
    for (k, val) in obj {
        match k.as_str() {
            "title" => match Title::parse(val) {
                Ok(t) => f.title = Some(t),
                Err(e) => errors.push(e),
            },
            "body" => match Body::parse(val) {
                Ok(b) => f.body = Some(b),
                Err(e) => errors.push(e),
            },
            k if READ_ONLY.contains(&k) => errors.push(err(k, "is read-only")),
            k => errors.push(err(k, "unknown field")),
        }
    }
    Some(f)
}

pub fn parse_create(v: &Value) -> Result<NewNote, Vec<FieldError>> {
    let mut errors = Vec::new();
    if let Some(f) = parse_fields(v, &mut errors) {
        if !f.has_title_key {
            errors.push(err("title", "is required"));
        }
        if errors.is_empty() {
            if let Some(title) = f.title {
                return Ok(NewNote { title, body: f.body.unwrap_or(Body(String::new())) });
            }
        }
    }
    Err(errors)
}

pub fn parse_patch(v: &Value) -> Result<NotePatch, Vec<FieldError>> {
    let mut errors = Vec::new();
    if let Some(f) = parse_fields(v, &mut errors) {
        if f.count == 0 {
            errors.push(err("$", "at least one of title, body is required"));
        }
        if errors.is_empty() {
            return Ok(NotePatch { title: f.title, body: f.body });
        }
    }
    Err(errors)
}

#[derive(Debug, PartialEq)]
pub enum Precondition {
    /// Missing header, empty, or a list containing `*`: 428.
    Required,
    /// Versions named by the strong, canonically formatted entity tags in the list.
    /// Anything else (weak, unquoted, `"01"`) can never match, so it contributes nothing.
    Versions(Vec<i64>),
}

impl Precondition {
    /// Strong comparison (RFC 9110 8.8.3.2): some entry must be byte-equal to the current ETag.
    pub fn matches(&self, current: i64) -> bool {
        matches!(self, Precondition::Versions(v) if v.contains(&current))
    }
}

pub fn parse_if_match(h: Option<&str>) -> Precondition {
    let Some(h) = h else { return Precondition::Required };
    let entries: Vec<&str> = h.split(',').map(str::trim).filter(|e| !e.is_empty()).collect();
    if entries.is_empty() || entries.contains(&"*") {
        return Precondition::Required;
    }
    let versions = entries
        .iter()
        .filter_map(|e| {
            let n: i64 = e.strip_prefix('"')?.strip_suffix('"')?.parse().ok()?;
            (etag(n) == *e).then_some(n)
        })
        .collect();
    Precondition::Versions(versions)
}

pub fn etag(version: i64) -> String {
    format!("\"{version}\"")
}

pub fn is_json_content_type(h: Option<&str>) -> bool {
    h.is_some_and(|v| v.split(';').next().unwrap_or("").trim().eq_ignore_ascii_case("application/json"))
}

pub fn bearer_token(h: Option<&str>) -> Option<&str> {
    let (scheme, rest) = h?.trim().split_once(' ')?;
    let tok = rest.trim();
    (scheme.eq_ignore_ascii_case("bearer") && !tok.is_empty()).then_some(tok)
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn fields<T: std::fmt::Debug>(r: Result<T, Vec<FieldError>>) -> Vec<String> {
        r.unwrap_err().into_iter().map(|e| e.field).collect()
    }

    #[test]
    fn title_is_trimmed_and_counted_in_code_points() {
        assert_eq!(parse_create(&json!({"title": "  hi  "})).unwrap().title.as_str(), "hi");
        assert!(parse_create(&json!({"title": "😀".repeat(200)})).is_ok());
        assert_eq!(fields(parse_create(&json!({"title": "😀".repeat(201)}))), ["title"]);
        assert_eq!(fields(parse_create(&json!({"title": "   "}))), ["title"]);
    }

    #[test]
    fn create_reports_every_failing_field() {
        let mut f = fields(parse_create(&json!({"title": 4, "body": 5, "foo": 1, "version": 2})));
        f.sort();
        assert_eq!(f, ["body", "foo", "title", "version"]);
        assert_eq!(fields(parse_create(&json!({"body": "x"}))), ["title"]);
        assert_eq!(fields(parse_create(&json!([1]))), ["$"]);
        assert_eq!(fields(parse_create(&Value::Null)), ["$"]);
    }

    #[test]
    fn body_defaults_empty_and_is_capped() {
        assert_eq!(parse_create(&json!({"title": "t"})).unwrap().body.as_str(), "");
        assert!(parse_create(&json!({"title": "t", "body": "b".repeat(100_000)})).is_ok());
        assert_eq!(fields(parse_create(&json!({"title": "t", "body": "b".repeat(100_001)}))), ["body"]);
    }

    #[test]
    fn patch_rules() {
        assert_eq!(fields(parse_patch(&json!({}))), ["$"]);
        assert_eq!(fields(parse_patch(&json!({"authorId": "carol"}))), ["authorId"]);
        let p = parse_patch(&json!({"body": "x"})).unwrap();
        assert!(p.title.is_none() && p.body.is_some());
    }

    #[test]
    fn if_match_parsing() {
        let v = |x: &[i64]| Precondition::Versions(x.to_vec());
        assert_eq!(parse_if_match(None), Precondition::Required);
        assert_eq!(parse_if_match(Some("")), Precondition::Required);
        assert_eq!(parse_if_match(Some("*")), Precondition::Required);
        assert_eq!(parse_if_match(Some("\"1\", *")), Precondition::Required);
        assert_eq!(parse_if_match(Some("\"3\"")), v(&[3]));
        assert_eq!(parse_if_match(Some("\"9\", \"1\"")), v(&[9, 1]));
        assert_eq!(parse_if_match(Some("3")), v(&[]));
        assert_eq!(parse_if_match(Some("\"01\"")), v(&[]));
        assert_eq!(parse_if_match(Some("W/\"3\"")), v(&[]));
        assert_eq!(parse_if_match(Some("W/\"1\", \"2\"")), v(&[2]));
        assert!(parse_if_match(Some("\"9\", \"1\"")).matches(1));
        assert!(!parse_if_match(Some("\"8\", \"9\"")).matches(1));
    }

    #[test]
    fn trim_uses_unicode_white_space_only() {
        let t = |s: &str| parse_create(&json!({"title": s})).map(|n| n.title.as_str().to_string());
        assert_eq!(t("\u{a0}hi\u{3000}").unwrap(), "hi");
        assert!(t("\u{a0}\u{2003}").is_err());
        assert!(t("\u{200b}").is_ok());
        assert!(t("\u{feff}").is_ok());
        assert!(t(&format!("{}", "e\u{301}".repeat(100))).is_ok());
        assert!(t(&format!("{}", "e\u{301}".repeat(101))).is_err());
    }

    #[test]
    fn non_object_bodies_name_root() {
        for v in [json!([]), json!("x"), json!(1), Value::Null] {
            assert_eq!(fields(parse_create(&v)), ["$"]);
        }
        assert_eq!(fields(parse_create(&json!({"title":"t","__proto__":{}}))), ["__proto__"]);
    }

    #[test]
    fn headers() {
        assert!(is_json_content_type(Some("application/json; charset=utf-8")));
        assert!(!is_json_content_type(Some("text/plain")));
        assert!(!is_json_content_type(None));
        assert_eq!(bearer_token(Some("Bearer abc")), Some("abc"));
        assert_eq!(bearer_token(Some("Basic abc")), None);
        assert_eq!(bearer_token(None), None);
        assert_eq!(etag(2), "\"2\"");
    }
}

